/**
 * Static brand assets: the shield mark, favicon, social preview, manifest and
 * the pre-paint theme script. The PNG copy of the social preview lives in
 * ./ogImagePng (generated by scripts/render-og.ts from ogImageSvg).
 */
export { ogImagePng } from "./ogImagePng";

/** Theme ids the picker offers ("system" follows prefers-color-scheme). */
export const THEME_IDS = ["light", "dark", "steel", "glass"] as const;
export type ThemeId = (typeof THEME_IDS)[number];

/** Browser chrome colour (meta theme-color) for each theme. */
export const THEME_COLORS: Record<ThemeId, string> = {
  light: "#fbfaf8",
  dark: "#161716",
  steel: "#0c0d0f",
  glass: "#0b0d12",
};

/* Geometric shield on a 32-unit grid: a faceted outline with the left half solid. */
const SHIELD_OUTER = "M16 2 28 6.2v10.2L16 30 4 16.4V6.2Z";
const SHIELD_INNER = "M16 6.2 24.2 9.1v5.9L16 24.4 7.8 15V9.1Z";
const SHIELD_HALF = "M16 6.2v18.2L7.8 15V9.1Z";

/** One-colour mark, used as a CSS mask for .brand-mark so it takes the theme's text colour. */
export const markSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="32" height="32">
  <path fill-rule="evenodd" d="${SHIELD_OUTER}${SHIELD_INNER}"/>
  <path d="${SHIELD_HALF}"/>
</svg>`;

export const faviconSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="32" height="32">
  <rect width="32" height="32" rx="6" fill="#0c0d0f"/>
  <g transform="translate(3.2 3.2) scale(.8)">
    <path fill="#f2f0ea" fill-rule="evenodd" d="${SHIELD_OUTER}${SHIELD_INNER}"/>
    <path fill="#c5cdc8" d="${SHIELD_HALF}"/>
  </g>
</svg>`;

const SERIF = "Charter, 'Bitstream Charter', 'Iowan Old Style', Georgia, serif";
/* resvg only tries the first family it is given, so the font the PNG is rendered with comes first. */
const SANS = "'DejaVu Sans', 'IBM Plex Sans', Helvetica, Arial, sans-serif";
const MONO = "'DejaVu Sans Mono', 'IBM Plex Mono', Menlo, monospace";

/** 1200x630 social preview in the Steel & Ink palette. */
export const ogImageSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 630" width="1200" height="630">
  <rect width="1200" height="630" fill="#0c0d0f"/>
  <path d="M96 112H1104M96 534H1104" stroke="#2a2d31" stroke-width="1"/>
  <path d="M96 112H260" stroke="#c5cdc8" stroke-width="3"/>
  <text x="96" y="84" font-family="${MONO}" font-size="20" letter-spacing="3" fill="#8e908c">AEGIS / DISCORD MODERATION</text>
  <text x="96" y="262" font-family="${SERIF}" font-size="76" fill="#f2f0ea">A moderation bot</text>
  <text x="96" y="350" font-family="${SERIF}" font-size="76" fill="#f2f0ea">for Discord.</text>
  <text x="96" y="418" font-family="${SANS}" font-size="27" fill="#a9aba7">Cases, automod, appeals, tickets and logging,</text>
  <text x="96" y="456" font-family="${SANS}" font-size="27" fill="#a9aba7">set up with slash commands.</text>
  <g transform="translate(852 150) scale(8)">
    <path fill="#f2f0ea" fill-rule="evenodd" d="${SHIELD_OUTER}${SHIELD_INNER}"/>
    <path fill="#c5cdc8" d="${SHIELD_HALF}"/>
  </g>
  <text x="96" y="580" font-family="${MONO}" font-size="22" fill="#c5cdc8">/warn <tspan fill="#8e908c">user:</tspan>@spammer <tspan fill="#8e908c">reason:</tspan>invites</text>
  <text x="1104" y="580" text-anchor="end" font-family="${MONO}" font-size="20" fill="#8e908c">Aegis</text>
</svg>`;

export const manifest = JSON.stringify(
  {
    name: "Aegis — Discord Moderation Bot",
    short_name: "Aegis",
    description:
      "A Discord moderation bot: cases, automod, appeals, tickets and logging, set up with slash commands.",
    start_url: "/",
    display: "standalone",
    background_color: "#fbfaf8",
    theme_color: "#fbfaf8",
    icons: [
      { src: "/assets/favicon.svg", sizes: "any", type: "image/svg+xml", purpose: "any" },
    ],
  },
  null,
  2
);

/**
 * Runs in <head> before first paint (served as /assets/theme-init.js, so it
 * stays within the CSP): applies the saved theme, or the system light/dark
 * preference, so the page never flashes the wrong palette.
 */
export const themeInitScript = `(function(){var r=document.documentElement;r.classList.add("js");var t=null;try{t=localStorage.getItem("aegis-theme");}catch(e){}var c=${JSON.stringify(THEME_COLORS)};var a=t;if(!t||!c.hasOwnProperty(t)){t="system";a=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light";}r.setAttribute("data-theme",a);r.setAttribute("data-theme-setting",t);var m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute("content",c[a]);})();`;
